def parse_quantity(text):
    value = int(text)
    if value < 0:
        return None
    return value

def summarize(values):
    total = 0
    for value in values:
        total = total + value
    return len(values), total

def main():
    raw = input()
    values = []
    for part in raw.split():
        try:
            value = parse_quantity(part)
        except ValueError:
            print("변환 제외:", part)
            continue
        if value is None:
            print("범위 제외:", part)
            continue
        values.append(value)
    count, total = summarize(values)
    print("개수:", count)
    print("합계:", total)

if __name__ == "__main__":
    main()

